const src = $json.body ?? $json;
const text = String(src.message ?? '').trim();
const budget = Number(src.budget ?? 0);
const email = String(src.email ?? '').trim().toLowerCase();
const urgent = /today|urgent|asap|this week/i.test(text);
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
let priority = 'normal';
let reason = 'default';
if (budget >= 2000 && urgent) { priority = 'high'; reason = 'budget_and_urgency'; }
else if (budget >= 2000) { priority = 'high'; reason = 'budget'; }
else if (urgent) { priority = 'high'; reason = 'urgency'; }
return [{
  json: {
    ok: validEmail,
    lead: {
      name: String(src.name ?? '').trim(),
      email,
      company: String(src.company ?? '').trim()
    },
    triage: { priority, reason },
    validation: validEmail ? [] : ['invalid_email']
  }
}];
